nodes.text_raw:
:root {
  color-scheme: dark;
  --sky-top: #4779d8;
  --sky-bottom: #102d58;
  --accent: #ffd166;
  --accent-rgb: 255, 209, 102;
  --text: #f7fbff;
  --muted: rgba(236, 245, 255, 0.68);
  --panel: rgba(7, 25, 52, 0.52);
  --panel-border: rgba(255, 255, 255, 0.16);
  --shadow: rgba(4, 15, 34, 0.4);
}

* {
  box-sizing: border-box;
}

html,
body {
  min-height: 100%;
  margin: 0;
}

body {
  min-width: 320px;
  min-height: 100vh;
  overflow-x: hidden;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--text);
  background:
    radial-gradient(circle at 16% 12%, rgba(255,255,255,.17), transparent 24%),
    radial-gradient(circle at 86% 82%, rgba(var(--accent-rgb),.16), transparent 25%),
    linear-gradient(145deg, var(--sky-top), var(--sky-bottom));
  transition: background 700ms ease;
}

body::before,
body::after {
  content: "";
  position: fixed;
  pointer-events: none;
  border-radius: 50%;
  filter: blur(4px);
  opacity: .55;
}

body::before {
  width: 420px;
  height: 420px;
  left: -150px;
  bottom: -180px;
  background: radial-gradient(circle, rgba(255,255,255,.13), transparent 66%);
}

body::after {
  width: 360px;
  height: 360px;
  right: -100px;
  top: -115px;
  background: radial-gradient(circle, rgba(var(--accent-rgb),.15), transparent 68%);
}

body.theme-clear {
  --sky-top: #448cf0;
  --sky-bottom: #173b76;
  --accent: #ffd36a;
  --accent-rgb: 255, 211, 106;
}

body.theme-cloud {
  --sky-top: #6f88a8;
  --sky-bottom: #253d5b;
  --accent: #d8e8f7;
  --accent-rgb: 216, 232, 247;
}

body.theme-rain {
  --sky-top: #506f91;
  --sky-bottom: #162c48;
  --accent: #69d2ff;
  --accent-rgb: 105, 210, 255;
}

body.theme-storm {
  --sky-top: #4d4e70;
  --sky-bottom: #18172d;
  --accent: #ffd765;
  --accent-rgb: 255, 215, 101;
}

body.theme-snow {
  --sky-top: #8ba9c5;
  --sky-bottom: #354f6e;
  --accent: #e9f8ff;
  --accent-rgb: 233, 248, 255;
}

body.theme-fog {
  --sky-top: #8799a6;
  --sky-bottom: #3c4a56;
  --accent: #e1e8ec;
  --accent-rgb: 225, 232, 236;
}

body.theme-night {
  --sky-top: #263d72;
  --sky-bottom: #080d25;
  --accent: #f5e6a5;
  --accent-rgb: 245, 230, 165;
}

main {
  position: relative;
  z-index: 1;
  width: 100%;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 36px;
}

.weather-card {
  width: min(1120px, 100%);
  min-height: 650px;
  position: relative;
  overflow: hidden;
  border: 1px solid var(--panel-border);
  border-radius: 38px;
  background:
    linear-gradient(130deg, rgba(255,255,255,.12), transparent 42%),
    rgba(5, 20, 43, .46);
  box-shadow:
    0 36px 90px var(--shadow),
    inset 0 1px 0 rgba(255,255,255,.18);
  backdrop-filter: blur(24px) saturate(120%);
  -webkit-backdrop-filter: blur(24px) saturate(120%);
}

.weather-card::before {
  content: "";
  position: absolute;
  width: 460px;
  height: 460px;
  right: -175px;
  top: -210px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(var(--accent-rgb),.17), transparent 68%);
  pointer-events: none;
}

.loading-view,
.error-view {
  min-height: 650px;
  padding: 64px;
  display: grid;
  place-content: center;
  text-align: center;
}

.loader {
  width: 54px;
  height: 54px;
  margin: 0 auto 24px;
  border-radius: 50%;
  border: 2px solid rgba(255,255,255,.18);
  border-top-color: var(--accent);
  animation: spin .9s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.loading-view h1,
.error-view h1 {
  margin: 0;
  font-size: clamp(1.9rem, 4vw, 3.2rem);
  letter-spacing: -.04em;
}

.loading-view p,
.error-view p {
  max-width: 560px;
  margin: 14px auto 0;
  color: var(--muted);
  line-height: 1.65;
}

.error-symbol {
  width: 72px;
  height: 72px;
  display: grid;
  place-items: center;
  margin: 0 auto 24px;
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 24px;
  background: rgba(255,255,255,.08);
  color: var(--accent);
  font-size: 2rem;
  font-weight: 700;
}

.weather-content {
  min-height: 650px;
  display: grid;
  grid-template-rows: auto 1fr auto;
  padding: 42px 46px 38px;
  animation: reveal .65s cubic-bezier(.2,.8,.2,1) both;
}

@keyframes reveal {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 28px;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 11px;
  color: var(--muted);
  font-size: .75rem;
  font-weight: 750;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.location-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 5px rgba(var(--accent-rgb),.13);
}

.location-name {
  max-width: 720px;
  margin: 0;
  font-size: clamp(2rem, 4.2vw, 3.8rem);
  line-height: .98;
  letter-spacing: -.055em;
  overflow-wrap: anywhere;
}

.date-block {
  flex: 0 0 auto;
  padding-top: 3px;
  color: var(--muted);
  text-align: right;
  line-height: 1.45;
}

.date-block strong {
  display: block;
  color: var(--text);
  font-size: 1rem;
  font-weight: 650;
}

.hero {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  align-items: center;
  min-height: 330px;
  gap: 30px;
}

.temperature-row {
  display: flex;
  align-items: flex-start;
  gap: 16px;
}

.temperature {
  font-size: clamp(5.6rem, 10vw, 8.6rem);
  font-weight: 250;
  line-height: .85;
  letter-spacing: -.09em;
  font-variant-numeric: tabular-nums;
}

.degree {
  padding-top: 2px;
  color: var(--accent);
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 350;
  line-height: 1;
}

.reading-label {
  margin: 15px 0 0 7px;
  color: var(--muted);
  font-size: .76rem;
  font-weight: 700;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.condition {
  margin: 22px 0 0;
  font-size: clamp(1.35rem, 2.4vw, 2rem);
  font-weight: 560;
  letter-spacing: -.025em;
}

.summary-line {
  margin: 8px 0 0;
  color: var(--muted);
  font-size: .96rem;
}

.visual-wrap {
  position: relative;
  min-height: 290px;
  display: grid;
  place-items: center;
}

.weather-visual {
  position: relative;
  width: 280px;
  height: 230px;
  transform: translateY(-2px);
}

.sun,
.moon {
  position: absolute;
  left: 92px;
  top: 19px;
  width: 116px;
  height: 116px;
  border-radius: 50%;
  transition: opacity .3s ease;
}

.sun {
  background: var(--accent);
  box-shadow:
    0 0 0 18px rgba(var(--accent-rgb),.08),
    0 0 60px rgba(var(--accent-rgb),.45);
}

.sun::before,
.sun::after {
  content: "";
  position: absolute;
  inset: -25px;
  border-radius: 50%;
  border: 1px dashed rgba(var(--accent-rgb),.35);
  animation: orbit 22s linear infinite;
}

.sun::after {
  inset: -42px;
  opacity: .48;
  animation-direction: reverse;
  animation-duration: 32s;
}

@keyframes orbit {
  to { transform: rotate(360deg); }
}

.moon {
  display: none;
  background: #f5e6a5;
  box-shadow: 0 0 45px rgba(245,230,165,.3);
}

.moon::after {
  content: "";
  position: absolute;
  width: 105px;
  height: 105px;
  left: 31px;
  top: -12px;
  border-radius: 50%;
  background: #172955;
}

body.theme-night .sun {
  display: none;
}

body.theme-night .moon {
  display: block;
}

.cloud {
  position: absolute;
  left: 40px;
  top: 111px;
  width: 205px;
  height: 70px;
  border-radius: 50px;
  background: linear-gradient(145deg, #f8fcff, #bdd0e2);
  filter: drop-shadow(0 18px 17px rgba(4,16,35,.24));
}

.cloud::before,
.cloud::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  background: inherit;
}

.cloud::before {
  width: 92px;
  height: 92px;
  left: 35px;
  top: -49px;
}

.cloud::after {
  width: 71px;
  height: 71px;
  right: 30px;
  top: -31px;
}

.weather-visual.clear .cloud {
  opacity: 0;
  transform: translateY(20px);
}

.weather-visual.clear .sun {
  left: 82px;
  top: 46px;
  width: 128px;
  height: 128px;
}

.precipitation {
  position: absolute;
  top: 191px;
  left: 63px;
  width: 165px;
  height: 38px;
  display: flex;
  justify-content: space-around;
  opacity: 0;
}

.rain-drop {
  width: 3px;
  height: 22px;
  border-radius: 4px;
  background: #78dcff;
  transform: rotate(20deg);
  box-shadow: 0 0 8px rgba(120,220,255,.5);
  animation: rainfall 1.1s ease-in infinite;
}

.rain-drop:nth-child(2) { animation-delay: -.55s; }
.rain-drop:nth-child(3) { animation-delay: -.25s; }
.rain-drop:nth-child(4) { animation-delay: -.8s; }

@keyframes rainfall {
  from { transform: translateY(-6px) rotate(20deg); opacity: 0; }
  35% { opacity: 1; }
  to { transform: translateY(16px) rotate(20deg); opacity: 0; }
}

.weather-visual.rain .precipitation,
.weather-visual.storm .precipitation {
  opacity: 1;
}

.snowflakes {
  position: absolute;
  top: 188px;
  left: 60px;
  width: 170px;
  display: none;
  justify-content: space-around;
  color: white;
  font-size: 1.2rem;
}

.snowflakes span {
  animation: snowfall 2s ease-in-out infinite;
}

.snowflakes span:nth-child(2) { animation-delay: -.7s; }
.snowflakes span:nth-child(3) { animation-delay: -1.3s; }
.snowflakes span:nth-child(4) { animation-delay: -.3s; }

@keyframes snowfall {
  0%, 100% { transform: translateY(-4px) rotate(0); opacity: .4; }
  50% { transform: translateY(14px) rotate(90deg); opacity: 1; }
}

.weather-visual.snow .snowflakes {
  display: flex;
}

.lightning {
  display: none;
  position: absolute;
  left: 128px;
  top: 177px;
  width: 27px;
  height: 54px;
  background: #ffd65c;
  clip-path: polygon(56% 0, 100% 0, 67% 38%, 95% 38%, 20% 100%, 39% 53%, 10% 53%);
  filter: drop-shadow(0 0 8px rgba(255,214,92,.8));
  animation: flash 2.8s steps(1) infinite;
}

@keyframes flash {
  0%, 12%, 16%, 100% { opacity: 1; }
  13%, 15% { opacity: .15; }
}

.weather-visual.storm .lightning {
  display: block;
}

.weather-visual.storm .cloud,
.weather-visual.rain .cloud {
  background: linear-gradient(145deg, #cdd9e6, #71869d);
}

.fog-lines {
  display: none;
  position: absolute;
  left: 35px;
  top: 185px;
  width: 215px;
}

.fog-lines i {
  display: block;
  height: 4px;
  margin: 12px 0;
  border-radius: 5px;
  background: rgba(239,247,250,.7);
}

.fog-lines i:nth-child(1) { width: 80%; margin-left: 13%; }
.fog-lines i:nth-child(2) { width: 100%; }
.fog-lines i:nth-child(3) { width: 66%; margin-left: 20%; }

.weather-visual.fog .fog-lines {
  display: block;
}

.weather-visual.fog .cloud {
  opacity: .62;
}

.detail-grid {
  position: absolute;
  right: 2px;
  bottom: 7px;
  display: flex;
  gap: 9px;
}

.detail-pill {
  min-width: 104px;
  padding: 12px 14px;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 17px;
  background: rgba(5,20,43,.28);
  backdrop-filter: blur(10px);
}

.detail-pill span {
  display: block;
  margin-bottom: 4px;
  color: var(--muted);
  font-size: .65rem;
  font-weight: 750;
  letter-spacing: .1em;
  text-transform: uppercase;
}

.detail-pill strong {
  font-size: 1rem;
  font-weight: 650;
  white-space: nowrap;
}

.bottom-panel {
  display: grid;
  grid-template-columns: 235px 1fr;
  gap: 25px;
  align-items: stretch;
}

.range-panel,
.chart-panel {
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 25px;
  background: rgba(4,18,39,.26);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.05);
}

.range-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  padding: 21px 20px;
  gap: 12px;
}

.range-item + .range-item {
  border-left: 1px solid rgba(255,255,255,.12);
  padding-left: 18px;
}

.range-label,
.chart-title {
  color: var(--muted);
  font-size: .68rem;
  font-weight: 750;
  letter-spacing: .11em;
  text-transform: uppercase;
}

.range-value {
  display: block;
  margin-top: 8px;
  font-size: 2rem;
  font-weight: 450;
  letter-spacing: -.04em;
}

.range-value small {
  color: var(--accent);
  font-size: .9rem;
  vertical-align: top;
}

.chart-panel {
  position: relative;
  min-height: 128px;
  padding: 18px 20px 12px;
  overflow: hidden;
}

.chart-head {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}

.chart-hint {
  color: rgba(236,245,255,.48);
  font-size: .7rem;
}

#hourly-chart {
  display: block;
  width: 100%;
  height: 82px;
  margin-top: 3px;
  overflow: visible;
}

.chart-tooltip {
  position: absolute;
  z-index: 3;
  pointer-events: none;
  transform: translate(-50%, -100%);
  padding: 7px 9px;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 10px;
  background: rgba(5,18,38,.9);
  box-shadow: 0 8px 20px rgba(0,0,0,.2);
  font-size: .72rem;
  white-space: nowrap;
  opacity: 0;
  transition: opacity .12s ease;
}

.chart-tooltip strong {
  color: var(--accent);
}

[hidden] {
  display: none !important;
}

@media (max-width: 850px) {
  main { padding: 18px; }

  .weather-content {
    padding: 32px 28px;
  }

  .hero {
    grid-template-columns: 1fr;
    padding-top: 45px;
  }

  .visual-wrap {
    min-height: 245px;
  }

  .bottom-panel {
    grid-template-columns: 1fr;
  }

  .date-block {
    display: none;
  }
}

@media (max-width: 560px) {
  .weather-card {
    border-radius: 26px;
  }

  .weather-content {
    padding: 27px 21px;
  }

  .location-name {
    font-size: 2.3rem;
  }

  .detail-grid {
    position: static;
    margin-top: 14px;
  }

  .visual-wrap {
    min-height: 330px;
  }

  .range-panel {
    grid-template-columns: 1fr 1fr;
  }

  .chart-hint {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }
}

(() => {
  "use strict";

  const $ = (id) => document.getElementById(id);
  const params = new URLSearchParams(window.location.search);
  const now = new Date();
  const today = [
    now.getFullYear(),
    String(now.getMonth() + 1).padStart(2, "0"),
    String(now.getDate()).padStart(2, "0")
  ].join("-");

  const rawLat = params.get("lat");
  const rawLon = params.get("lon");
  const rawName = params.get("name");
  const rawDate = params.get("date");

  const lat = rawLat === null || rawLat.trim() === "" ? 52.52 : Number(rawLat);
  const lon = rawLon === null || rawLon.trim() === "" ? 13.405 : Number(rawLon);
  const name = rawName === null || rawName.trim() === "" ? "Berlin" : rawName.trim();
  const targetDate = rawDate === null || rawDate.trim() === "" ? today : rawDate.trim();

  const loadingView = $("loading-view");
  const errorView = $("error-view");
  const contentView = $("weather-content");
  const card = $("weather-card");

  function fail(message) {
    loadingView.hidden = true;
    contentView.hidden = true;
    errorView.hidden = false;
    $("error-message").textContent = message;
    card.setAttribute("aria-busy", "false");
    document.title = "Weather unavailable";
  }

  function validDateString(value) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
    const [year, month, day] = value.split("-").map(Number);
    const date = new Date(year, month - 1, day);
    return date.getFullYear() === year &&
      date.getMonth() === month - 1 &&
      date.getDate() === day;
  }

  function dateObject(value) {
    const [year, month, day] = value.split("-").map(Number);
    return new Date(year, month - 1, day, 12, 0, 0);
  }

  if (!Number.isFinite(lat) || lat < -90 || lat > 90) {
    fail("The “lat” parameter must be a number between −90 and 90.");
    return;
  }

  if (!Number.isFinite(lon) || lon < -180 || lon > 180) {
    fail("The “lon” parameter must be a number between −180 and 180.");
    return;
  }

  if (!validDateString(targetDate)) {
    fail("The “date” parameter must be a real calendar date in YYYY-MM-DD format.");
    return;
  }

  if (name.length > 120) {
    fail("The location name is too long. Please use a label under 120 characters.");
    return;
  }

  $("loading-location").textContent = `Loading weather for ${name}…`;

  const weatherCodes = {
    0:  ["Clear sky", "clear"],
    1:  ["Mainly clear", "clear"],
    2:  ["Partly cloudy", "cloud"],
    3:  ["Overcast", "cloud"],
    45: ["Foggy", "fog"],
    48: ["Freezing fog", "fog"],
    51: ["Light drizzle", "rain"],
    53: ["Drizzle", "rain"],
    55: ["Heavy drizzle", "rain"],
    56: ["Freezing drizzle", "rain"],
    57: ["Heavy freezing drizzle", "rain"],
    61: ["Light rain", "rain"],
    63: ["Rain", "rain"],
    65: ["Heavy rain", "rain"],
    66: ["Freezing rain", "rain"],
    67: ["Heavy freezing rain", "rain"],
    71: ["Light snow", "snow"],
    73: ["Snowfall", "snow"],
    75: ["Heavy snowfall", "snow"],
    77: ["Snow grains", "snow"],
    80: ["Light rain showers", "rain"],
    81: ["Rain showers", "rain"],
    82: ["Heavy rain showers", "rain"],
    85: ["Snow showers", "snow"],
    86: ["Heavy snow showers", "snow"],
    95: ["Thunderstorm", "storm"],
    96: ["Thunderstorm with hail", "storm"],
    99: ["Severe thunderstorm with hail", "storm"]
  };

  function weatherInfo(code) {
    return weatherCodes[Number(code)] || ["Variable conditions", "cloud"];
  }

  function round(value) {
    return Number.isFinite(Number(value)) ? Math.round(Number(value)) : null;
  }

  function pickDailyValue(daily, key) {
    if (!daily || !Array.isArray(daily.time)) return null;
    const index = daily.time.indexOf(targetDate);
    if (index < 0 || !Array.isArray(daily[key])) return null;
    return daily[key][index];
  }

  function getHourlyRows(data) {
    const hourly = data.hourly;
    if (!hourly || !Array.isArray(hourly.time) || !Array.isArray(hourly.temperature_2m)) {
      return [];
    }

    const rows = [];
    for (let i = 0; i < hourly.time.length; i++) {
      if (String(hourly.time[i]).slice(0, 10) !== targetDate) continue;
      const temperature = Number(hourly.temperature_2m[i]);
      if (!Number.isFinite(temperature)) continue;

      rows.push({
        time: hourly.time[i],
        temperature,
        code: Array.isArray(hourly.weather_code) ? hourly.weather_code[i] : null,
        wind: Array.isArray(hourly.wind_speed_10m) ? hourly.wind_speed_10m[i] : null,
        humidity: Array.isArray(hourly.relative_humidity_2m) ? hourly.relative_humidity_2m[i] : null
      });
    }
    return rows;
  }

  function representativeRow(rows) {
    if (!rows.length) return null;
    return rows.reduce((best, row) => {
      const hour = Number(String(row.time).slice(11, 13));
      const bestHour = Number(String(best.time).slice(11, 13));
      return Math.abs(hour - 12) < Math.abs(bestHour - 12) ? row : best;
    });
  }

  function formatCoordinate(value, positive, negative) {
    const direction = value >= 0 ? positive : negative;
    return `${Math.abs(value).toFixed(2)}° ${direction}`;
  }

  function formatDate(value) {
    const date = dateObject(value);
    return {
      weekday: new Intl.DateTimeFormat(undefined, { weekday: "long" }).format(date),
      full: new Intl.DateTimeFormat(undefined, {
        month: "long",
        day: "numeric",
        year: "numeric"
      }).format(date)
    };
  }

  function setTheme(kind, isNight) {
    document.body.className = "";
    document.body.classList.add(`theme-${isNight ? "night" : kind}`);
    $("weather-visual").className = `weather-visual ${kind}`;
  }

  function makeSummary(min, max, wind, unit) {
    const spread = Number.isFinite(min) && Number.isFinite(max) ? Math.round(max - min) : null;
    const parts = [];
    if (spread !== null) parts.push(`${spread}° temperature range`);
    if (Number.isFinite(wind)) {
      parts.push(wind < 12 ? "light winds" : wind < 30 ? "a steady breeze" : "strong winds");
    }
    return parts.length ? parts.join(" · ") : `Weather values shown in ${unit}`;
  }

  function renderChart(rows, unit) {
    const svg = $("hourly-chart");
    const panel = $("chart-panel");
    const tooltip = $("chart-tooltip");

    if (rows.length < 2) {
      svg.innerHTML =
        '<text x="350" y="52" text-anchor="middle" fill="rgba(236,245,255,.62)" font-size="13">No hourly temperatures available</text>';
      return;
    }

    const W = 700;
    const H = 90;
    const left = 8;
    const right = 8;
    const top = 13;
    const bottom = 23;
    const temperatures = rows.map(row => row.temperature);
    let min = Math.min(...temperatures);
    let max = Math.max(...temperatures);
    if (max === min) {
      max += 1;
      min -= 1;
    }

    const points = rows.map((row, index) => {
      const x = left + index * ((W - left - right) / (rows.length - 1));
      const y = top + (max - row.temperature) / (max - min) * (H - top - bottom);
      return { x, y, row };
    });

    const linePath = points.map((point, index) =>
      `${index === 0 ? "M" : "L"} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`
    ).join(" ");

    const areaPath =
      `${linePath} L ${points[points.length - 1].x.toFixed(2)} ${H - bottom + 2} ` +
      `L ${points[0].x.toFixed(2)} ${H - bottom + 2} Z`;

    const labelIndices = [...new Set([
      0,
      Math.round((rows.length - 1) * .25),
      Math.round((rows.length - 1) * .5),
      Math.round((rows.length - 1) * .75),
      rows.length - 1
    ])];

    const labels = labelIndices.map(index => {
      const point = points[index];
      const hour = String(point.row.time).slice(11, 16);
      return `<text x="${point.x}" y="86" text-anchor="${index === 0 ? "start" : index === rows.length - 1 ? "end" : "middle"}" fill="rgba(236,245,255,.5)" font-size="10">${hour}</text>`;
    }).join("");

    svg.innerHTML = `
      <defs>
        <linearGradient id="area-gradient" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="rgb(${getComputedStyle(document.body).getPropertyValue("--accent-rgb")})" stop-opacity=".31"/>
          <stop offset="100%" stop-color="rgb(${getComputedStyle(document.body).getPropertyValue("--accent-rgb")})" stop-opacity="0"/>
        </linearGradient>
      </defs>
      <line x1="8" y1="${H - bottom + 2}" x2="${W - 8}" y2="${H - bottom + 2}" stroke="rgba(255,255,255,.09)" stroke-width="1"/>
      <path d="${areaPath}" fill="url(#area-gradient)"/>
      <path d="${linePath}" fill="none" stroke="var(--accent)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
      <line id="hover-line" x1="0" y1="${top}" x2="0" y2="${H - bottom + 2}" stroke="rgba(255,255,255,.32)" stroke-width="1" opacity="0"/>
      <circle id="hover-point" cx="0" cy="0" r="4.5" fill="var(--accent)" stroke="rgba(5,18,38,.9)" stroke-width="2" opacity="0"/>
      ${labels}
      <rect id="chart-hit" x="0" y="0" width="${W}" height="${H}" fill="transparent"/>
    `;

    const hit = $("chart-hit");
    const hoverLine = $("hover-line");
    const hoverPoint = $("hover-point");

    function move(event) {
      const rect = svg.getBoundingClientRect();
      const localX = Math.max(0, Math.min(W, (event.clientX - rect.left) / rect.width * W));
      const index = Math.max(0, Math.min(points.length - 1,
        Math.round((localX - left) / (W - left - right) * (points.length - 1))
      ));
      const point = points[index];
      const displayedHour = String(point.row.time).slice(11, 16);

      hoverLine.setAttribute("x1", point.x);
      hoverLine.setAttribute("x2", point.x);
      hoverLine.setAttribute("opacity", "1");
      hoverPoint.setAttribute("cx", point.x);
      hoverPoint.setAttribute("cy", point.y);
      hoverPoint.setAttribute("opacity", "1");

      tooltip.innerHTML = `${displayedHour} &nbsp; <strong>${Math.round(point.row.temperature)}°${unit}</strong>`;
      tooltip.style.opacity = "1";
      tooltip.style.left = `${(point.x / W) * rect.width}px`;
      tooltip.style.top = `${Math.max(49, (point.y / H) * rect.height + 27)}px`;
    }

    function leave() {
      hoverLine.setAttribute("opacity", "0");
      hoverPoint.setAttribute("opacity", "0");
      tooltip.style.opacity = "0";
    }

    hit.addEventListener("pointermove", move);
    hit.addEventListener("pointerleave", leave);
    panel.addEventListener("pointerleave", leave);
  }

  async function loadWeather() {
    const isPast = targetDate < today;
    const endpoint = isPast ? "/api/om/archive" : "/api/om/forecast";
    const query = new URLSearchParams({
      latitude: String(lat),
      longitude: String(lon),
      start_date: targetDate,
      end_date: targetDate,
      timezone: "auto",
      temperature_unit: "celsius",
      wind_speed_unit: "kmh",
      hourly: "temperature_2m,weather_code,wind_speed_10m,relative_humidity_2m",
      daily: "weather_code,temperature_2m_max,temperature_2m_min,wind_speed_10m_max"
    });

    if (targetDate === today && !isPast) {
      query.set("current", "temperature_2m,apparent_temperature,weather_code,wind_speed_10m,relative_humidity_2m,is_day");
    }

    let response;
    try {
      response = await fetch(`${endpoint}?${query.toString()}`, {
        headers: { "Accept": "application/json" }
      });
    } catch (error) {
      throw new Error("A network error prevented the weather service from responding. Please check your connection and try again.");
    }

    let data;
    try {
      data = await response.json();
    } catch (error) {
      throw new Error("The weather service returned an unreadable response.");
    }

    if (!response.ok || data.error) {
      const reason = data && data.reason ? String(data.reason) : `Request failed with status ${response.status}.`;
      throw new Error(reason);
    }

    const rows = getHourlyRows(data);
    const representative = representativeRow(rows);

    if (!representative) {
      throw new Error(`No hourly weather data was available for ${targetDate} at these coordinates.`);
    }

    const current = targetDate === today && data.current ? data.current : null;
    const useCurrent = current && Number.isFinite(Number(current.temperature_2m));
    const temperature = useCurrent ? Number(current.temperature_2m) : representative.temperature;
    const code = useCurrent && current.weather_code !== null
      ? current.weather_code
      : (representative.code ?? pickDailyValue(data.daily, "weather_code"));

    const wind = useCurrent && Number.isFinite(Number(current.wind_speed_10m))
      ? Number(current.wind_speed_10m)
      : Number(representative.wind);

    const humidity = useCurrent && Number.isFinite(Number(current.relative_humidity_2m))
      ? Number(current.relative_humidity_2m)
      : Number(representative.humidity);

    const min = Number(pickDailyValue(data.daily, "temperature_2m_min"));
    const max = Number(pickDailyValue(data.daily, "temperature_2m_max"));

    if (!Number.isFinite(temperature) || !Number.isFinite(min) || !Number.isFinite(max)) {
      throw new Error("The weather response did not contain the required temperature values.");
    }

    const [description, kind] = weatherInfo(code);
    const units = data.hourly_units || {};
    const temperatureUnit = String(units.temperature_2m || "°C").replace("°", "") || "C";
    const windUnit = data.current_units?.wind_speed_10m || units.wind_speed_10m || "km/h";
    const isNight = Boolean(useCurrent && Number(current.is_day) === 0 && kind === "clear");

    const formattedDate = formatDate(targetDate);
    $("location-name").textContent = name;
    $("coordinates").textContent =
      `${formatCoordinate(lat, "N", "S")}  ·  ${formatCoordinate(lon, "E", "W")}`;
    $("date-weekday").textContent = formattedDate.weekday;
    $("date-full").textContent = formattedDate.full;
    $("temperature").textContent = String(round(temperature));
    $("reading-label").textContent = useCurrent ? "Current temperature" : "Midday temperature";
    $("condition").textContent = description;
    $("temp-min").textContent = String(round(min));
    $("temp-max").textContent = String(round(max));
    $("wind-speed").textContent = Number.isFinite(wind) ? `${round(wind)} ${windUnit}` : "Unavailable";
    $("humidity").textContent = Number.isFinite(humidity) ? `${round(humidity)}%` : "Unavailable";
    $("summary-line").textContent = makeSummary(min, max, wind, `°${temperatureUnit}`);
    $("hourly-chart").setAttribute(
      "aria-label",
      `Hourly temperature chart for ${name} on ${formattedDate.full}`
    );

    setTheme(kind, isNight);
    renderChart(rows, temperatureUnit);

    document.title = `${round(temperature)}° · ${name} Weather`;
    loadingView.hidden = true;
    errorView.hidden = true;
    contentView.hidden = false;
    card.setAttribute("aria-busy", "false");
  }

  loadWeather().catch(error => {
    fail(error && error.message
      ? error.message
      : "The weather could not be loaded because of an unexpected error.");
  });
})();
